array_utils.code:
getArraySize(array)
{
    if(!isdefined(array))
        return 0;

    return array.size;
}

randomizeArray(array)
{
    newArray = [];

    for(i = 0; i < array.size; i++)
    {
        newArray[newArray.size] = array[i];
    }

    for(i = 0; i < newArray.size; i++)
    {
        j = randomint(newArray.size);
        temp = newArray[i];
        newArray[i] = newArray[j];
        newArray[j] = temp;
    }

    return newArray;
}

removeFromArray(array, item)
{
    newArray = [];

    for(i = 0; i < array.size; i++)
    {
        if(array[i] != item)
            newArray[newArray.size] = array[i];
    }

    return newArray;
}

getArrayKeys(array)
{
    keys = [];

    foreach(key, value in array)
    {
        keys[keys.size] = key;
    }

    return keys;
}
